body.script:
new isvek.Bvi({
    target: '.bvi-open',
    fontSize: 14,
    panelFixed: false,
    panelHide: true,
})

    $(document).ready(function () {
        const links = $('.links-carousel');

        links.owlCarousel({
            loop: true,
            margin: 16,
            nav: false,
            dots: false,
            autoplay: true,
            center: false,
            autoplayTimeout: 2000,
            smartSpeed: 1000,
            autoplayHoverPause: true,
            onInitialized: function (e) {
                const carousel = $(e.target);
                const dots = initCarouselLines(e.item.count, i => carousel.trigger('to.owl.carousel', [i]));
                carousel.on('changed.owl.carousel', e => dots.setActive(e.item.index % e.item.count));
            },
            responsive: {
                0: {
                    items: 1,
                    center: true
                },
                545: {
                    items: 2,
                    center: false
                },
                810: {
                    items: 3,
                    center: true
                },
                1068: {
                    items: 4
                },
                1600: {
                    items: 5
                }
            },
        });
    });

