    jQuery(document).ready(function () {
        $('.btn-adaptive').click(function () {
            //  var a = $(this).attr("href");
           // console.log("test")
            OpenWindowMobile('https://www.uzgastrade.uz/', 420, 568, "media");
            return false

        });

        function OpenWindowMobile(b, d, a, c) {
            if (!c) {
                c = window
            }
            if (!d) {
                d = 800
            }
            if (!a) {
                a = 600
            }
            var f = (screen.width - d) / 2;
            var e = window.open(b, c, "left=" + f + ",top=100,width=" + d + ",height=" + a + ",directories=no,menubar=no,status=yes,resizable=yes,scrollbars=yes,toolbar=no");
            if (e.opener == null) {
                e.opener = self
            }
            e.focus()
        }
    });
